## 3. Result-Generation Logic (form data → recommendation)

Source: `client/src/lib/padQMLogic.ts`

```typescript
/**
 * PAD Quality Measures Logic Engine
 * Based on: 2026 ACC/AHA Clinical Performance and Quality Measures for Patients With
 * Peripheral Artery Disease (Goodney PP, Ross EG, Bruckel JT, et al.)
 * Published: Circ Popul Health Outcomes. 2025;18:e000142 / JACC 2026 Jan 8
 * PMID: 41505788
 *
 * 7 Performance Measures (PM-1 through PM-7) — appropriate for public reporting / pay-for-performance
 * 8 Quality Measures (QM-1 through QM-8) — for quality improvement; not yet ready for public reporting
 *
 * Measure types:
 *   - Performance Measures (PM): Based on Class 1 or Class 3 recommendations from 2024 ACC/AHA PAD Guideline
 *   - Quality Measures (QM): Some based on Class 2 recommendations; for internal QI use
 *
 * General exclusion rule: For all but PM-6 and PM-7, if clinician determines care is
 * inappropriate for the patient, that patient is excluded. For ALL measures, patients
 * who decline treatment/care are excluded.
 */

// ─── Types ────────────────────────────────────────────────────────────────────

export type MeasureType = "performance" | "quality";
export type MeasureResult = "pass" | "fail" | "excluded" | "not_applicable";
export type GuidelineClass = "1" | "2a" | "2b" | "3_harm" | "3_no_benefit";

export interface PADQMMeasure {
  id: string; // e.g., "PM-1", "QM-3"
  type: MeasureType;
  title: string;
  description: string;
  numerator: string;
  denominator: string;
  exclusions: string[];
  guidelineClass: GuidelineClass;
  loe: string; // Level of Evidence
  rationale: string;
  isNew2026: boolean; // New measure added in 2026 (vs. carried over from prior version)
}

export interface PADQMPatientInput {
  // Demographics
  age: number;
  hasDiabetes: boolean;
  hasHypertension: boolean;
  hasAtherosclerosis: boolean; // documented PAD diagnosis

  // PAD Classification
  padPresentation: "asymptomatic" | "claudication" | "clti" | "ali" | "post_revascularization";
  ankleArmIndex?: number; // ABI value if measured
  abiMeasured: boolean;
  abiDocumented: boolean; // documented in chart within 12 months of encounter

  // Revascularization context
  hadRevascularization: boolean;
  revascularizationType?: "endovascular" | "surgical" | "hybrid";
  saphenousVeinAssessedPreOp?: boolean; // for surgical revascularization

  // Medical therapies
  onAntiplateletOrAnticoagulant: boolean;
  antithromboticTherapyPrescribed: boolean;
  antithromboticContraindicated: boolean;
  antithromboticDeclined: boolean;

  onStatinOrLipidLowering: boolean;
  statinPrescribed: boolean;
  statinContraindicated: boolean;
  statinDeclined: boolean;

  onACEInhibitorOrARB: boolean;
  aceInhibitorPrescribed: boolean;
  aceInhibitorContraindicated: boolean;
  aceInhibitorDeclined: boolean;

  // Blood pressure
  bpMeasured: boolean;
  systolicBP?: number;
  bpGoalAchieved: boolean; // SBP < 130 mmHg per 2024 guideline
  bpManagementDocumented: boolean;
  bpManagementContraindicated: boolean;
  bpManagementDeclined: boolean;

  // Diabetes management
  hba1cMeasured: boolean;
  hba1cValue?: number;
  diabetesManagementDocumented: boolean;
  diabetesManagementContraindicated: boolean;
  diabetesManagementDeclined: boolean;

  // Tobacco
  tobaccoUseScreened: boolean;
  tobaccoUser: boolean;
  cessationCounselingProvided: boolean;
  cessationPharmacotherapyOffered: boolean;

  // Exercise
  exerciseTherapyReferralMade: boolean;
  exerciseTherapyContraindicated: boolean;
  exerciseTherapyDeclined: boolean;
  claudicationSymptoms: boolean;

  // Foot care (CLTI / diabetes)
  preventiveFootCareProvided: boolean;
  footCareContraindicated: boolean;
  footCareDeclined: boolean;
  hasFootRisk: boolean; // diabetes + PAD = high risk for foot complications

  // Novel lipid-lowering agents (PCSK9i, inclisiran, bempedoic acid)
  onNovelLipidAgent: boolean;
  novelLipidAgentConsidered: boolean;
  ldlcValue?: number;
  ldlcAtGoal: boolean; // LDL-C < 70 mg/dL for high-risk PAD

  // Health disparities
  disparityScreeningDocumented: boolean;
  raceEthnicityDocumented: boolean;
  socialDeterminantsDocumented: boolean;

  // Multidisciplinary care (CLTI)
  multidisciplinaryDiscussionDocumented: boolean;
  multidisciplinaryTeamInvolved: boolean; // vascular surgery, wound care, podiatry, etc.
  cltiDiagnosis: boolean;
}

export interface PADQMMeasureScore {
  measure: PADQMMeasure;
  result: MeasureResult;
  eligible: boolean; // patient meets denominator criteria
  passed: boolean; // numerator criteria met
  excluded: boolean; // clinician/patient exclusion applies
  exclusionReason?: string;
  details: string; // human-readable explanation of the result
}

export interface PADQMAssessmentResult {
  scores: PADQMMeasureScore[];
  performanceMeasuresSummary: {
    total: number;
    passed: number;
    failed: number;
    excluded: number;
    notApplicable: number;
    passRate: number; // percentage
  };
  qualityMeasuresSummary: {
    total: number;
    passed: number;
    failed: number;
    excluded: number;
    notApplicable: number;
    passRate: number;
  };
  overallPassRate: number;
  priorityGaps: PADQMMeasureScore[]; // failed measures sorted by measure type
  recommendations: string[];
}

