// ─── Scoring Engine ───────────────────────────────────────────────────────────

export function scorePADQMMeasure(
  measure: PADQMMeasure,
  input: PADQMPatientInput
): PADQMMeasureScore {
  let eligible = false;
  let passed = false;
  let excluded = false;
  let exclusionReason: string | undefined;
  let details = "";

  switch (measure.id) {
    case "PM-1": {
      // ABI Testing
      eligible =
        input.padPresentation !== undefined &&
        (input.hasAtherosclerosis ||
          input.padPresentation === "claudication" ||
          input.padPresentation === "clti" ||
          input.padPresentation === "ali");
      if (!eligible) {
        details = "Patient does not meet denominator criteria (no PAD diagnosis or suspicion).";
        break;
      }
      if (input.abiMeasured === false && input.abiDocumented === false) {
        // Check for exclusion
        excluded = false; // no documented exclusion provided
        passed = false;
        details = "ABI testing not documented within 12 months. Measure FAILS.";
      } else if (input.abiDocumented) {
        passed = true;
        details = `ABI documented (value: ${input.ankleArmIndex !== undefined ? input.ankleArmIndex : "on file"}). Measure PASSES.`;
      } else {
        passed = false;
        details = "ABI measured but not documented in chart. Measure FAILS.";
      }
      break;
    }

    case "PM-2": {
      // Statin Therapy
      eligible = input.hasAtherosclerosis;
      if (!eligible) {
        details = "Patient does not have established PAD diagnosis.";
        break;
      }
      if (input.statinContraindicated) {
        excluded = true;
        exclusionReason = "Statin therapy contraindicated (documented intolerance or contraindication).";
        details = exclusionReason;
        break;
      }
      if (input.statinDeclined) {
        excluded = true;
        exclusionReason = "Patient declined statin therapy.";
        details = exclusionReason;
        break;
      }
      passed = input.statinPrescribed || input.onStatinOrLipidLowering;
      details = passed
        ? "Statin therapy prescribed or documented. Measure PASSES."
        : "Statin therapy not prescribed and not documented. Measure FAILS.";
      break;
    }

    case "PM-3": {
      // Antithrombotic Therapy
      eligible =
        input.padPresentation === "claudication" ||
        input.padPresentation === "clti" ||
        input.hadRevascularization;
      if (!eligible) {
        details = "Patient does not have symptomatic PAD or prior revascularization.";
        break;
      }
      if (input.antithromboticContraindicated) {
        excluded = true;
        exclusionReason = "Antithrombotic therapy contraindicated (documented).";
        details = exclusionReason;
        break;
      }
      if (input.antithromboticDeclined) {
        excluded = true;
        exclusionReason = "Patient declined antithrombotic therapy.";
        details = exclusionReason;
        break;
      }
      passed = input.antithromboticTherapyPrescribed || input.onAntiplateletOrAnticoagulant;
      details = passed
        ? "Antithrombotic therapy prescribed or documented. Measure PASSES."
        : "Antithrombotic therapy not prescribed and not documented. Measure FAILS.";
      break;
    }

    case "PM-4": {
      // Blood Pressure Management
      eligible = input.hasAtherosclerosis && input.hasHypertension;
      if (!eligible) {
        details = "Patient does not have both PAD and hypertension.";
        break;
      }
      if (input.bpManagementContraindicated) {
        excluded = true;
        exclusionReason = "BP management contraindicated (documented).";
        details = exclusionReason;
        break;
      }
      if (input.bpManagementDeclined) {
        excluded = true;
        exclusionReason = "Patient declined BP management.";
        details = exclusionReason;
        break;
      }
      passed = input.bpMeasured && input.bpManagementDocumented;
      if (passed && input.systolicBP !== undefined) {
        details = `BP measured (SBP: ${input.systolicBP} mmHg) and management documented. ${input.bpGoalAchieved ? "Goal SBP <130 mmHg achieved." : "Goal SBP <130 mmHg NOT yet achieved — intensify therapy."} Measure PASSES.`;
      } else if (passed) {
        details = "BP measured and management documented. Measure PASSES.";
      } else {
        details = `BP ${!input.bpMeasured ? "not measured" : "measured but management not documented"}. Measure FAILS.`;
      }
      break;
    }

    case "PM-5": {
      // ACE Inhibitor / ARB
      eligible =
        input.padPresentation === "claudication" ||
        input.padPresentation === "clti" ||
        input.hadRevascularization;
      if (!eligible) {
        details = "Patient does not have symptomatic PAD.";
        break;
      }
      if (input.aceInhibitorContraindicated) {
        excluded = true;
        exclusionReason = "ACE inhibitor/ARB contraindicated (documented).";
        details = exclusionReason;
        break;
      }
      if (input.aceInhibitorDeclined) {
        excluded = true;
        exclusionReason = "Patient declined ACE inhibitor/ARB therapy.";
        details = exclusionReason;
        break;
      }
      passed = input.aceInhibitorPrescribed || input.onACEInhibitorOrARB;
      details = passed
        ? "ACE inhibitor or ARB prescribed or documented. Measure PASSES."
        : "ACE inhibitor/ARB not prescribed and not documented. Measure FAILS.";
      break;
    }

    case "PM-6": {
      // Tobacco Use Screening — NO general clinician-appropriateness exclusion
      eligible = input.hasAtherosclerosis;
      if (!eligible) {
        details = "Patient does not have established PAD.";
        break;
      }
      if (!input.tobaccoUseScreened) {
        passed = false;
        details = "Tobacco use screening not documented. Measure FAILS.";
        break;
      }
      if (!input.tobaccoUser) {
        passed = true;
        details = "Tobacco use screened — patient is a non-user. Measure PASSES.";
        break;
      }
      // Current tobacco user — must offer cessation counseling AND pharmacotherapy
      passed = input.cessationCounselingProvided && input.cessationPharmacotherapyOffered;
      details = passed
        ? "Tobacco use screened, patient is a current user, cessation counseling AND pharmacotherapy offered. Measure PASSES."
        : `Tobacco use screened, patient is a current user, but ${!input.cessationCounselingProvided ? "cessation counseling not documented" : "cessation pharmacotherapy not offered"}. Measure FAILS.`;
      break;
    }

    case "PM-7": {
      // Supervised Exercise Therapy — NO general clinician-appropriateness exclusion
      eligible = input.claudicationSymptoms && input.padPresentation === "claudication";
      if (!eligible) {
        details = "Patient does not have claudication symptoms (SET is not indicated for CLTI or asymptomatic PAD).";
        break;
      }
      if (input.exerciseTherapyDeclined) {
        excluded = true;
        exclusionReason = "Patient declined supervised exercise therapy referral.";
        details = exclusionReason;
        break;
      }
      passed = input.exerciseTherapyReferralMade;
      details = passed
        ? "Supervised exercise therapy referral documented. Measure PASSES."
        : "Supervised exercise therapy referral not documented. Measure FAILS.";
      break;
    }

    case "QM-1": {
      // Diabetes Management
      eligible = input.hasAtherosclerosis && input.hasDiabetes;
      if (!eligible) {
        details = "Patient does not have both PAD and diabetes mellitus.";
        break;
      }
      if (input.diabetesManagementContraindicated) {
        excluded = true;
        exclusionReason = "Diabetes management contraindicated (documented).";
        details = exclusionReason;
        break;
      }
      if (input.diabetesManagementDeclined) {
        excluded = true;
        exclusionReason = "Patient declined diabetes management.";
        details = exclusionReason;
        break;
      }
      passed = input.hba1cMeasured && input.diabetesManagementDocumented;
      if (passed && input.hba1cValue !== undefined) {
        details = `HbA1c measured (${input.hba1cValue}%) and management documented. ${input.hba1cValue > 7 ? "HbA1c above target — intensify management." : "HbA1c at or below 7% target."} Measure PASSES.`;
      } else if (passed) {
        details = "HbA1c measured and diabetes management documented. Measure PASSES.";
      } else {
        details = `${!input.hba1cMeasured ? "HbA1c not measured" : "HbA1c measured but management not documented"}. Measure FAILS.`;
      }
      break;
    }

    case "QM-2": {
      // Preventive Foot Care
      eligible = input.hasAtherosclerosis && (input.hasDiabetes || input.cltiDiagnosis || input.hasFootRisk);
      if (!eligible) {
        details = "Patient does not have PAD with diabetes, CLTI, or high foot risk.";
        break;
      }
      if (input.footCareContraindicated) {
        excluded = true;
        exclusionReason = "Foot care contraindicated (documented).";
        details = exclusionReason;
        break;
      }
      if (input.footCareDeclined) {
        excluded = true;
        exclusionReason = "Patient declined foot care education/examination.";
        details = exclusionReason;
        break;
      }
      passed = input.preventiveFootCareProvided;
      details = passed
        ? "Preventive foot care education and examination documented. Measure PASSES."
        : "Preventive foot care not documented. Measure FAILS.";
      break;
    }

    case "QM-3": {
      // Novel Lipid-Lowering Therapy
      eligible =
        input.hasAtherosclerosis &&
        !input.ldlcAtGoal &&
        input.ldlcValue !== undefined &&
        input.ldlcValue >= 70;
      if (!eligible) {
        details = "Patient does not meet criteria (PAD with LDL-C ≥70 mg/dL despite statin therapy).";
        break;
      }
      passed = input.novelLipidAgentConsidered || input.onNovelLipidAgent;
      details = passed
        ? `Novel lipid-lowering agent considered or prescribed (LDL-C: ${input.ldlcValue} mg/dL). Measure PASSES.`
        : `LDL-C ${input.ldlcValue} mg/dL above goal (≥70 mg/dL) — novel lipid-lowering agent not considered. Measure FAILS.`;
      break;
    }

    case "QM-4": {
      // Health Disparities Assessment
      eligible = input.hasAtherosclerosis;
      if (!eligible) {
        details = "Patient does not have established PAD.";
        break;
      }
      passed = input.raceEthnicityDocumented && input.socialDeterminantsDocumented;
      details = passed
        ? "Race/ethnicity and social determinants of health documented. Measure PASSES."
        : `${!input.raceEthnicityDocumented ? "Race/ethnicity not documented" : "Race/ethnicity documented but SDOH not documented"}. Measure FAILS.`;
      break;
    }

    case "QM-5": {
      // Saphenous Vein Assessment
      eligible =
        input.hadRevascularization &&
        input.revascularizationType === "surgical";
      if (!eligible) {
        details = "Patient did not undergo surgical bypass revascularization.";
        break;
      }
      if (input.saphenousVeinAssessedPreOp === undefined) {
        passed = false;
        details = "Preoperative saphenous vein mapping not documented. Measure FAILS.";
        break;
      }
      passed = input.saphenousVeinAssessedPreOp === true;
      details = passed
        ? "Preoperative saphenous vein mapping documented. Measure PASSES."
        : "Preoperative saphenous vein mapping not performed or not documented. Measure FAILS.";
      break;
    }

    case "QM-6": {
      // Multidisciplinary Team Discussion for CLTI
      eligible = input.cltiDiagnosis;
      if (!eligible) {
        details = "Patient does not have CLTI (rest pain, ischemic ulcer, or gangrene).";
        break;
      }
      if (input.padPresentation === "ali") {
        excluded = true;
        exclusionReason = "Acute limb ischemia requiring emergency revascularization — multidisciplinary discussion not feasible.";
        details = exclusionReason;
        break;
      }
      passed = input.multidisciplinaryDiscussionDocumented && input.multidisciplinaryTeamInvolved;
      details = passed
        ? "Multidisciplinary team discussion documented prior to definitive treatment. Measure PASSES."
        : "Multidisciplinary team discussion not documented. Measure FAILS.";
      break;
    }

    case "QM-7": {
      // Shared Decision-Making
      eligible =
        input.hasAtherosclerosis &&
        (input.hadRevascularization || input.padPresentation === "clti" || input.padPresentation === "claudication");
      if (!eligible) {
        details = "Patient does not meet criteria for shared decision-making measure.";
        break;
      }
      if (input.padPresentation === "ali") {
        excluded = true;
        exclusionReason = "Emergency revascularization for acute limb ischemia — shared decision-making not feasible.";
        details = exclusionReason;
        break;
      }
      passed = input.multidisciplinaryDiscussionDocumented; // reuse as proxy for SDM documentation
      details = passed
        ? "Shared decision-making discussion documented. Measure PASSES."
        : "Shared decision-making discussion not documented. Measure FAILS.";
      break;
    }

    case "QM-8": {
      // Post-Revascularization Surveillance
      eligible = input.hadRevascularization;
      if (!eligible) {
        details = "Patient has not undergone lower extremity revascularization.";
        break;
      }
      passed = input.abiDocumented; // post-revascularization ABI as proxy
      details = passed
        ? "Post-revascularization ABI documented. Measure PASSES (duplex ultrasound should also be documented per full measure specification)."
        : "Post-revascularization ABI not documented. Measure FAILS.";
      break;
    }

    default:
      details = "Unknown measure ID.";
  }

  const result: MeasureResult = !eligible
    ? "not_applicable"
    : excluded
    ? "excluded"
    : passed
    ? "pass"
    : "fail";

  return {
    measure,
    result,
    eligible,
    passed,
    excluded,
    exclusionReason,
    details,
  };
}

export function assessPADQualityMeasures(input: PADQMPatientInput): PADQMAssessmentResult {
  const scores = PAD_QM_MEASURES.map((measure) => scorePADQMMeasure(measure, input));

  const pms = scores.filter((s) => s.measure.type === "performance");
  const qms = scores.filter((s) => s.measure.type === "quality");

  const summarize = (group: PADQMMeasureScore[]) => {
    const eligible = group.filter((s) => s.eligible);
    const passed = eligible.filter((s) => s.passed && !s.excluded).length;
    const failed = eligible.filter((s) => !s.passed && !s.excluded).length;
    const excluded = eligible.filter((s) => s.excluded).length;
    const notApplicable = group.filter((s) => !s.eligible).length;
    const denominator = passed + failed; // exclude excluded and N/A from rate
    return {
      total: group.length,
      passed,
      failed,
      excluded,
      notApplicable,
      passRate: denominator > 0 ? Math.round((passed / denominator) * 100) : 0,
    };
  };

  const pmSummary = summarize(pms);
  const qmSummary = summarize(qms);
  const allEligible = scores.filter((s) => s.eligible && !s.excluded);
  const overallPassRate =
    allEligible.length > 0
      ? Math.round((allEligible.filter((s) => s.passed).length / allEligible.length) * 100)
      : 0;

  const priorityGaps = scores
    .filter((s) => s.eligible && !s.excluded && !s.passed)
    .sort((a, b) => {
      // Performance measures first, then quality measures
      if (a.measure.type === "performance" && b.measure.type === "quality") return -1;
      if (a.measure.type === "quality" && b.measure.type === "performance") return 1;
      return 0;
    });

  const recommendations: string[] = [];
  for (const gap of priorityGaps) {
    switch (gap.measure.id) {
      case "PM-1":
        recommendations.push("Order ABI testing and document results within 12 months.");
        break;
      case "PM-2":
        recommendations.push("Prescribe high-intensity statin therapy (atorvastatin 40–80 mg or rosuvastatin 20–40 mg).");
        break;
      case "PM-3":
        recommendations.push("Prescribe antithrombotic therapy: aspirin 81 mg daily, clopidogrel 75 mg daily, or rivaroxaban 2.5 mg BID + aspirin 100 mg daily (COMPASS regimen).");
        break;
      case "PM-4":
        recommendations.push("Measure blood pressure and document management plan targeting SBP <130 mmHg.");
        break;
      case "PM-5":
        recommendations.push("Prescribe ACE inhibitor (e.g., ramipril 10 mg daily) or ARB for cardiovascular risk reduction.");
        break;
      case "PM-6":
        recommendations.push("Screen for tobacco use and offer cessation counseling + pharmacotherapy (varenicline preferred).");
        break;
      case "PM-7":
        recommendations.push("Refer patient to Medicare-covered supervised exercise therapy (SET) program for claudication.");
        break;
      case "QM-1":
        recommendations.push("Measure HbA1c and document diabetes management plan (target HbA1c <7% or individualized).");
        break;
      case "QM-2":
        recommendations.push("Perform foot examination and provide preventive foot care education (self-inspection, footwear, wound prevention).");
        break;
      case "QM-3":
        recommendations.push(`LDL-C ${input.ldlcValue !== undefined ? input.ldlcValue + " mg/dL" : "above goal"} — consider PCSK9 inhibitor (evolocumab or alirocumab), ezetimibe, bempedoic acid, or inclisiran.`);
        break;
      case "QM-4":
        recommendations.push("Document race/ethnicity and screen for social determinants of health (food, housing, transportation, insurance).");
        break;
      case "QM-5":
        recommendations.push("Perform preoperative duplex ultrasound saphenous vein mapping before bypass surgery.");
        break;
      case "QM-6":
        recommendations.push("Convene multidisciplinary team discussion (vascular surgery/IR + wound care/podiatry) before definitive CLTI treatment.");
        break;
      case "QM-7":
        recommendations.push("Document shared decision-making discussion including treatment options, risks/benefits, and patient preferences.");
        break;
      case "QM-8":
        recommendations.push("Document post-revascularization ABI and duplex ultrasound surveillance within 30 days of procedure.");
        break;
    }
  }

  return {
    scores,
    performanceMeasuresSummary: pmSummary,
    qualityMeasuresSummary: qmSummary,
    overallPassRate,
    priorityGaps,
    recommendations,
  };
}

// ─── Helper: Measure color coding ────────────────────────────────────────────

export function getMeasureResultColor(result: MeasureResult): string {
  switch (result) {
    case "pass":
      return "green";
    case "fail":
      return "red";
    case "excluded":
      return "yellow";
    case "not_applicable":
      return "gray";
  }
}

export function getMeasureResultLabel(result: MeasureResult): string {
  switch (result) {
    case "pass":
      return "PASS";
    case "fail":
      return "FAIL";
    case "excluded":
      return "EXCLUDED";
    case "not_applicable":
      return "N/A";
  }
}
